class Solution:
    def orangesRotting(self, grid: list[list[int]]) -> int:
        from collections import deque

        m, n = len(grid), len(grid[0])
        queue = deque()
        fresh = 0

        for r in range(m):
            for c in range(n):
                if grid[r][c] == 2:
                    queue.append((r, c))
                elif grid[r][c] == 1:
                    fresh += 1

        minutes = 0

        while queue and fresh:
            for _ in range(len(queue)):
                r, c = queue.popleft()

                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc

                    if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
                        grid[nr][nc] = 2
                        fresh -= 1
                        queue.append((nr, nc))

            minutes += 1

        return minutes if fresh == 0 else -1

class Solution:
    def generate(self, numRows):
        result = []

        for i in range(numRows):
            row = [1] * (i + 1)

            for j in range(1, i):
                row[j] = result[i - 1][j - 1] + result[i - 1][j]

            result.append(row)

        return result

class Solution:
    def numberOfSubarrays(self, nums: list[int], k: int) -> int:
        res = left = count = odds = 0

        for right in range(len(nums)):
            if nums[right] % 2 == 1:
                odds += 1
                count = 0

            while odds == k:
                if nums[left] % 2 == 1:
                    odds -= 1
                count += 1
                left += 1

            res += count

        return res

class Solution:
    def getIntersectionNode(self, headA: ListNode, headB: ListNode) -> Optional[ListNode]:
        a, b = headA, headB

        while a != b:
            a = a.next if a else headB
            b = b.next if b else headA

        return a

class Solution:
    def reverseList(self, head):
        prev = None
        current = head

        while current:
            next_node = current.next
            current.next = prev
            prev = current
            current = next_node

        return prev

class Solution:
    def minGroups(self, intervals: list[list[int]]) -> int:
        starts = sorted(l for l, r in intervals)
        ends = sorted(r for l, r in intervals)

        i = j = 0
        groups = 0
        max_groups = 0

        while i < len(intervals):
            if starts[i] <= ends[j]:
                groups += 1
                max_groups = max(max_groups, groups)
                i += 1
            else:
                groups -= 1
                j += 1

        return max_groups

class Solution:
    def reverseKGroup(self, head, k):
        dummy = ListNode(0, head)
        prev = dummy

        while True:
            curr = prev
            for _ in range(k):
                curr = curr.next
                if not curr:
                    return dummy.next

            tail = prev.next
            curr = tail.next

            for _ in range(k - 1):
                tail.next = curr.next
                curr.next = prev.next
                prev.next = curr
                curr = tail.next

            prev = tail

class Solution:
    def reversePairs(self, nums):
        def merge_sort(arr):
            if len(arr) <= 1:
                return 0

            mid = len(arr) // 2
            left = arr[:mid]
            right = arr[mid:]

            count = merge_sort(left) + merge_sort(right)

            j = 0
            for i in range(len(left)):
                while j < len(right) and left[i] > 2 * right[j]:
                    j += 1
                count += j

            arr[:] = sorted(left + right)

            return count

        return merge_sort(nums)

class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        n = len(isConnected)
        visited = [False] * n
        provinces = 0

        def dfs(city):
            visited[city] = True

            for nei in range(n):
                if isConnected[city][nei] == 1 and not visited[nei]:
                    dfs(nei)

        for i in range(n):
            if not visited[i]:
                provinces += 1
                dfs(i)

        return provinces

class Solution:
    def uniquePaths(self, m, n):
        dp = [1] * n

        for i in range(1, m):
            for j in range(1, n):
                dp[j] = dp[j] + dp[j - 1]

        return dp[n - 1]

class Solution:
    def subsets(self, nums: list[int]) -> list[list[int]]:
        result = []

        def backtrack(i, current):
            if i == len(nums):
                result.append(current[:])
                return

            backtrack(i + 1, current)

            current.append(nums[i])
            backtrack(i + 1, current)
            current.pop()

        backtrack(0, [])
        return result

class Solution:
    def search(self, nums: list[int], target: int) -> bool:
        left, right = 0, len(nums) - 1

        while left <= right:
            mid = (left + right) // 2

            if nums[mid] == target:
                return True

            if nums[left] == nums[mid] == nums[right]:
                left += 1
                right -= 1
                continue

            if nums[left] <= nums[mid]:
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1

        return False
